import {regions} from './data.js';
const pin=(x,y)=>`<circle class="pin" cx="${x}" cy="${y}" r="11"/><text class="pintext" x="${x}" y="${y+4}">1</text>`;
const txt=(x,y,t)=>`<text class="label" x="${x}" y="${y}">${t}</text>`;
export function diagram(type,target=null,labels=true){let s='',title='',desc='';
if(type==='regions'){title='Nine abdominopelvic regions';desc='Anterior view. Patient right is viewer left. Grid rows proceed superior to inferior.';s=`<path class="body" d="M110 38 Q85 65 99 100 L106 195 Q93 245 135 285 L265 285 Q307 245 294 195 L301 100 Q315 65 290 38 Q250 55 200 55 Q150 55 110 38Z"/>${txt(77,25,'PATIENT RIGHT')}${txt(242,25,'PATIENT LEFT')}`;regions.forEach((r,i)=>{let x=102+(i%3)*66,y=77+Math.floor(i/3)*63;s+=`<rect x="${x}" y="${y}" width="64" height="61" rx="2" fill="${i===target?'#d7a982':'#dfe7d6'}" stroke="#9dad96"/>`;if(labels){let words=r[0].split(' ');s+=`<text x="${x+32}" y="${y+27}" text-anchor="middle" style="font-size:9px">${words.map((w,j)=>`<tspan x="${x+32}" dy="${j?12:0}">${w}</tspan>`).join('')}</text>`}if(i===target)s+=pin(x+32,y+31)});s+=txt(137,315,'ANTERIOR VIEW • NOT TO SCALE');}
if(type==='cavities'){title='Body compartments, lateral view';desc='Person faces right. Cranial space is in the skull; vertebral canal descends posteriorly; thorax lies above abdomen and pelvis.';s=`<path class="body" d="M151 31 C170 6 214 8 222 39 L225 51 L242 67 L226 73 L224 99 L207 103 L206 117 Q263 128 266 168 L258 247 L242 294 L190 294 L164 260 L158 137 L149 99 Q129 65 151 31Z"/>`;let shapes=[`<ellipse cx="183" cy="53" rx="32" ry="31"/>`,`<path d="M155 87 L168 86 L179 248 L169 251Z"/>`,`<path d="M179 123 Q237 121 249 154 L249 184 Q220 165 181 185Z"/>`,`<path d="M182 193 Q220 173 249 193 L241 247 L184 247Z"/>`,`<path d="M184 253 L241 253 L230 280 L202 280Z"/>`];shapes.forEach((p,i)=>s+=`<g fill="${target===i?'#d4a077':i<2?'#bdcbb1':'#cbd9d7'}" stroke="#7d9584">${p}</g>`);if(labels)['Cranial','Vertebral','Thoracic','Abdominal','Pelvic'].forEach((n,i)=>{let y=[51,125,158,220,270][i];s+=`<path d="M${i===1?163:i===0?184:219} ${y}H${i===1?72:302}" stroke="#899b88"/>${txt(i===1?12:306,y+4,n)}`});if(target!==null)s+=pin(...[[183,53],[169,153],[215,153],[215,221],[217,266]][target]);s+=txt(50,315,'POSTERIOR ←   LATERAL VIEW   → ANTERIOR');}
if(type==='membrane'){title='Serous layers, enlarged section';desc='From cavity wall toward organ: parietal membrane, fluid-filled potential space, visceral membrane. Gap deliberately enlarged.';s=`<rect x="52" y="63" width="296" height="40" fill="#bbc9b2"/><rect x="52" y="103" width="296" height="10" fill="#4f7762"/><rect x="52" y="113" width="296" height="40" fill="#d2e3e9"/><rect x="52" y="153" width="296" height="10" fill="#a66746"/><rect x="52" y="163" width="296" height="77" rx="0" fill="#d6b198"/>${txt(62,87,'CAVITY WALL')}${txt(62,216,'ORGAN TISSUE')}${txt(56,291,'CROSS-SECTION • SPACE ENLARGED')}`;if(labels)s+=txt(68,48,'Parietal layer')+'<path d="M105 52L105 108" stroke="#315d50"/>'+txt(68,139,'Serous cavity + fluid')+txt(208,268,'Visceral layer')+'<path d="M275 252L275 158" stroke="#805f4e"/>';if(target!==null)s+=pin(270,[108,133,158][target]);}
if(type==='urinary'){title='Urinary structures, anterior view';desc='Two kidneys lie on the posterior abdominal wall, with ureters descending to the bladder and urethra exiting inferiorly. Right kidney is slightly lower.';s=`${txt(45,24,'PATIENT RIGHT')}${txt(245,24,'PATIENT LEFT')}<path d="M159 53 Q125 29 107 61 Q85 99 111 127 Q145 151 158 114 Q134 107 139 87 Q139 69 159 72Z" class="organ"/><path d="M241 44 Q275 20 293 52 Q315 90 289 118 Q255 142 242 105 Q266 98 261 78 Q261 60 241 63Z" class="organ"/><path d="M144 97 C168 109 160 178 176 216 M257 88 C231 110 240 178 223 216" fill="none" stroke="#b29369" stroke-width="6"/><path d="M167 214 Q200 195 232 214 Q246 246 215 268 L185 268 Q153 246 167 214Z" class="organ"/><path d="M200 267V301" stroke="#b29369" stroke-width="7"/>${txt(85,329,'ANTERIOR VIEW • SIMPLIFIED, NOT TO SCALE')}`;if(labels){s+=txt(34,85,'Kidney')+txt(265,168,'Ureter')+txt(244,242,'Urinary bladder')+txt(219,291,'Urethra')}if(target!==null)s+=pin(...[[117,88],[238,157],[200,241],[200,287]][target]);}
if(type==='female'){title='Female internal reproductive structures';desc='Anterior schematic showing paired ovaries lateral to uterine tubes, central uterus, cervix narrowing into vagina. Tube ends are open near ovaries.';s=`${txt(25,24,'PATIENT RIGHT')}${txt(255,24,'PATIENT LEFT')}<path d="M160 123 C127 99 126 68 91 81 Q66 92 77 112 M240 123 C273 99 274 68 309 81 Q334 92 323 112" fill="none" stroke="#af806b" stroke-width="10"/><path d="M77 106l-12 16m14-12l-2 20m5-20l10 16 M323 106l12 16m-14-12l2 20m-5-20l-10 16" stroke="#af806b" stroke-width="3"/><ellipse class="organ" cx="99" cy="139" rx="24" ry="15"/><ellipse class="organ" cx="301" cy="139" rx="24" ry="15"/><path class="organ" d="M157 112 Q200 91 243 112 Q249 139 227 170 Q210 192 213 216 L187 216 Q190 192 173 170 Q151 139 157 112Z"/><path d="M190 123 Q200 120 210 123 L201 181Z" fill="#edcfbb"/><path d="M187 216 Q180 246 185 284 L215 284 Q220 246 213 216Z" class="organ"/><path d="M185 234h30m-30 13h30m-30 13h30m-30 13h30" stroke="#b98e77"/>${txt(78,316,'ANTERIOR VIEW • SIMPLIFIED, NOT TO SCALE')}`;if(labels)s+=txt(55,175,'Ovary')+txt(249,66,'Uterine tube')+txt(244,194,'Uterus')+txt(235,263,'Vagina');if(target!==null)s+=pin(...[[99,139],[282,82],[218,151],[200,252]][target]);}
return `<div class="diagram"><svg viewBox="0 0 400 345" role="img" aria-label="${target!==null&&!labels?'Unlabeled anatomy identification diagram':title}"><title>${target!==null&&!labels?'Identify pin 1':title}</title>${labels?`<desc>${desc}</desc>`:''}${s}</svg></div>`;}
